    {
      "fieldKey": "pesticideName",
      "type": "DROPDOWN",
      "label": {
        "en": "Pesticide Name",
        "hi": "कीटनाशक का नाम"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": true,
      "displayOrder": 10,
      "optionSetKey": "pesticide__pesticide_name",
      "allowOther": true
    },
    {
      "fieldKey": "pesticideNameOther",
      "type": "TEXT",
      "label": {
        "en": "Please Specify",
        "hi": "कृपया निर्दिष्ट करें"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": false,
      "displayOrder": 20,
      "fieldLength": 80,
      "validation": {
        "maxLength": 80
      },
      "visibleWhen": {
        "field": "pesticideName",
        "operator": "equals",
        "value": "__other__"
      }
    },
    {
      "fieldKey": "pesticideUsage",
      "type": "TEXT",
      "label": {
        "en": "Pesticide Usage",
        "hi": "कीटनाशक उपयोग"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": false,
      "displayOrder": 30,
      "fieldLength": 120,
      "validation": {
        "maxLength": 120
      }
    },
    {
      "fieldKey": "pesticideType",
      "type": "RADIO",
      "label": {
        "en": "Pesticide Type",
        "hi": "कीटनाशक प्रकार"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": true,
      "displayOrder": 40,
      "optionSetKey": "pesticide__pesticide_type"
    },
    {
      "fieldKey": "pesticideDescription",
      "type": "TEXTAREA",
      "label": {
        "en": "Pesticide Description",
        "hi": "कीटनाशक विवरण"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": false,
      "displayOrder": 50,
      "fieldLength": 1000,
      "validation": {
        "maxLength": 1000
      }
    },
    {
      "fieldKey": "pesticideBrand",
      "type": "TEXT",
      "label": {
        "en": "Pesticide Brand",
        "hi": "कीटनाशक ब्रांड"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": false,
      "displayOrder": 60,
      "fieldLength": 80,
      "validation": {
        "maxLength": 80
      }
    },
    {
      "fieldKey": "qtyLiquid",
      "type": "NUMBER",
      "label": {
        "en": "Quantity (ml/Litre)",
        "hi": "मात्रा (मिली/लीटर)"
      },
      "sectionKey": "quantity",
      "sectionTitle": {
        "en": "Quantity & Unit",
        "hi": "मात्रा और इकाई"
      },
      "required": false,
      "displayOrder": 70,
      "validation": {
        "min": 0
      },
      "visibleWhen": {
        "field": "pesticideType",
        "operator": "equals",
        "value": "liquid"
      }
    },
    {
      "fieldKey": "qtyPowder",
      "type": "NUMBER",
      "label": {
        "en": "Quantity (gm/Kg)",
        "hi": "मात्रा (ग्राम/किग्रा)"
      },
      "sectionKey": "quantity",
      "sectionTitle": {
        "en": "Quantity & Unit",
        "hi": "मात्रा और इकाई"
      },
      "required": false,
      "displayOrder": 80,
      "validation": {
        "min": 0
      },
      "visibleWhen": {
        "field": "pesticideType",
        "operator": "equals",
        "value": "powder"
      }
    },
    {
      "fieldKey": "pesticideUnit",
      "type": "DROPDOWN",
      "label": {
        "en": "Pesticide Unit",
        "hi": "कीटनाशक इकाई"
      },
      "sectionKey": "quantity",
      "sectionTitle": {
        "en": "Quantity & Unit",
        "hi": "मात्रा और इकाई"
      },
      "required": false,
      "displayOrder": 90,
