      "label": {
        "en": "Price per g/ml",
        "hi": "प्रति ग्राम/मिली मूल्य"
      },
      "sectionKey": "pricing",
      "sectionTitle": {
        "en": "Pricing",
        "hi": "मूल्य निर्धारण"
      },
      "required": false,
      "displayOrder": 100,
      "validation": {
        "min": 0
      }
    },
    {
      "fieldKey": "pricePerKgL",
      "type": "DECIMAL",
