        "en": "Price per Kg/l",
        "hi": "प्रति किग्रा/लीटर मूल्य"
      },
      "sectionKey": "pricing",
      "sectionTitle": {
        "en": "Pricing",
        "hi": "मूल्य निर्धारण"
      },
      "required": false,
      "displayOrder": 110,
