        "hi": "प्रति 10 किग्रा मूल्य"
      },
      "sectionKey": "pricing",
      "sectionTitle": {
        "en": "Pricing",
        "hi": "मूल्य निर्धारण"
      },
      "required": false,
      "displayOrder": 120,
      "validation": {
        "min": 0
      }
    },
