      "fieldKey": "actualPrice",
      "type": "DECIMAL",
      "label": {
        "en": "Actual Price (₹)",
        "hi": "वास्तविक मूल्य (₹)"
      },
      "sectionKey": "pricing",
      "sectionTitle": {
        "en": "Pricing",
        "hi": "मूल्य निर्धारण"
      },
      "required": true,
      "displayOrder": 130,
      "common": true,
      "validation": {
        "min": 0
      }
    },
    {
      "fieldKey": "offeredPrice",
      "type": "DECIMAL",
      "label": {
        "en": "Offered Price (₹)",
        "hi": "प्रस्तावित मूल्य (₹)"
      },
      "sectionKey": "pricing",
      "sectionTitle": {
        "en": "Pricing",
        "hi": "मूल्य निर्धारण"
      },
      "required": true,
      "displayOrder": 140,
      "common": true,
      "validation": {
        "min": 0
      }
    },
    {
      "fieldKey": "discountPct",
      "type": "AUTO_CALC",
      "label": {
        "en": "Discount %",
        "hi": "छूट %"
      },
      "sectionKey": "pricing",
      "sectionTitle": {
        "en": "Pricing",
        "hi": "मूल्य निर्धारण"
      },
      "required": false,
      "displayOrder": 150,
      "common": true,
      "readOnly": true,
      "computed": {
        "formula": "(actualPrice - offeredPrice) / actualPrice * 100",
        "readOnly": true
      }
    },
    {
      "fieldKey": "isNegotiable",
      "type": "BOOLEAN",
      "label": {
        "en": "Is Negotiable?",
        "hi": "क्या मोल-भाव योग्य है?"
      },
      "sectionKey": "pricing",
      "sectionTitle": {
        "en": "Pricing",
        "hi": "मूल्य निर्धारण"
      },
      "required": false,
      "displayOrder": 160,
      "common": true
    },
