      "fieldKey": "images",
      "type": "IMAGE",
      "label": {
        "en": "Upload Images",
        "hi": "तस्वीरें अपलोड करें"
      },
      "sectionKey": "media",
      "sectionTitle": {
        "en": "Photos",
        "hi": "तस्वीरें"
      },
      "required": true,
      "displayOrder": 170,
      "multiple": true,
      "common": true,
      "validation": {
        "min": 1,
        "max": 10,
        "acceptedTypes": [
          "jpg",
          "png",
          "webp"
        ],
        "sources": [
          "camera",
          "gallery"
        ],
        "capture": true
      }
    },
    {
      "fieldKey": "useDefaultAddress",
      "type": "BOOLEAN",
      "label": {
        "en": "Use Default Address",
        "hi": "डिफ़ॉल्ट पते का उपयोग करें"
      },
      "sectionKey": "address",
      "sectionTitle": {
        "en": "Address",
        "hi": "पता"
      },
      "required": false,
      "displayOrder": 180,
      "common": true
    },
    {
      "fieldKey": "address",
      "type": "ADDRESS",
      "label": {
        "en": "Address",
        "hi": "पता"
      },
      "sectionKey": "address",
      "sectionTitle": {
        "en": "Address",
        "hi": "पता"
      },
      "required": true,
      "displayOrder": 190,
      "common": true,
      "visibleWhen": {
        "field": "useDefaultAddress",
        "operator": "equals",
        "value": false
      }
    }
  ]
}

